<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>فاکتور {{ $order->invoice_number }}</title><link rel="stylesheet" href="{{ asset('assets/css/app.css') }}"><style>body{background:#f7f5f0;color:#171611}.invoice{width:min(960px,calc(100% - 32px));margin:40px auto;background:#fff;border:1px solid #e8e3d9;padding:42px;border-radius:24px}.invoice-head{display:flex;justify-content:space-between;gap:30px;border-bottom:1px solid #e8e3d9;padding-bottom:24px;margin-bottom:24px}.invoice h1{margin:0;font-size:32px}.invoice small{color:#817b72}.invoice-table{width:100%;border-collapse:collapse;margin:28px 0}.invoice-table th,.invoice-table td{padding:14px 10px;border-bottom:1px solid #eeeae2;text-align:right}.invoice-total{margin-right:auto;width:min(420px,100%)}.invoice-total div{display:flex;justify-content:space-between;padding:8px 0}.invoice-total .grand{border-top:1px solid #222;margin-top:8px;padding-top:14px;font-size:20px}.print-btn{display:inline-flex;border:0;border-radius:999px;background:#171611;color:#fff;padding:12px 22px;cursor:pointer}@media print{body{background:#fff}.invoice{width:100%;margin:0;border:0;border-radius:0;padding:0}.print-btn{display:none}}@media(max-width:640px){.invoice{padding:22px}.invoice-head{display:grid}.invoice-table{font-size:12px}}</style></head><body><main class="invoice"><header class="invoice-head"><div><small>CARPET HOUSE / OFFICIAL INVOICE</small><h1>فاکتور فروش</h1><p>خانه فرش — فرش برای معماری ماندگار</p></div><div><b class="ltr">{{ $order->invoice_number }}</b><br><small>{{ $order->paid_at?->format('Y/m/d H:i') }}</small><p>سفارش: <span class="ltr">{{ $order->order_number }}</span></p></div></header><section><div><b>خریدار:</b> {{ $order->customer_name }} — <span class="ltr">{{ $order->phone }}</span></div><div><b>آدرس:</b> {{ collect($order->shipping_address)->filter()->implode('، ') }}</div></section><table class="invoice-table"><thead><tr><th>شرح</th><th>SKU</th><th>تعداد</th><th>قیمت واحد</th><th>جمع</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->product_name }}</td><td class="ltr">{{ $item->sku }}</td><td>{{ number_format($item->quantity) }}</td><td>{{ number_format($item->unit_price) }}</td><td>{{ number_format($item->total_price) }}</td></tr>@endforeach</tbody></table><div class="invoice-total"><div><span>جمع کالا</span><b>{{ number_format($order->subtotal) }} تومان</b></div><div><span>تخفیف</span><b>{{ number_format($order->discount_amount) }} تومان</b></div><div><span>ارسال</span><b>{{ number_format($order->shipping_amount) }} تومان</b></div><div class="grand"><span>مبلغ پرداخت‌شده</span><b>{{ number_format($order->total) }} تومان</b></div></div><p style="margin-top:28px;color:#817b72">کد پیگیری پرداخت: <span class="ltr">{{ $order->payment_ref_id }}</span></p><button class="print-btn" onclick="window.print()">چاپ فاکتور</button></main></body></html>
